@startuml

class FurnitureLine {
  + Name : string
}

class FurniturePiece {
  + Reference : string
  + Price : double
  + Type : string
}

class Component {
  + Code : int
  + ManufacturingPrice : double
  + Type : string
}

class PieceComponent {
  + Quantity : int
}

class Store {
  + Address : string
  + FaxNumber : string
}

class Order {
  + OrderNumber : int
  + Date : date
}

class OrderLine {
  + Quantity : int
}

FurnitureLine "1" *-- "*" FurniturePiece
FurniturePiece "1" *-- "1..*" PieceComponent
PieceComponent "*" -- "1" Component
FurniturePiece "*" -- "*" Store
Store "1" -- "*" Order : places
Order "1" *-- "*" OrderLine
OrderLine "*" -- "1" FurniturePiece

@enduml

